func MergeDuplicationERC20(tokens []common.Address, amounts []*big.Int) ([]common.Address, []*big.Int) {
	if len(tokens) != len(amounts) {
		return nil, nil
	}
	tokenAmountMap := make(map[common.Address]*big.Int, len(tokens))
	dupTokens := make([]common.Address, 0, len(tokens))
	for i, token := range tokens {
		if oldAmount, ok := tokenAmountMap[token]; ok {
			oldAmount.Add(oldAmount, amounts[i])
		} else {
			tokenAmountMap[token] = new(big.Int).Set(amounts[i])
			dupTokens = append(dupTokens, token)
		}
	}
	sort.Slice(dupTokens, func(i, j int) bool {
		return dupTokens[i].String() < dupTokens[j].String()
	})
	mergeTokens := make([]common.Address, 0, len(dupTokens))
	mergeAmounts := make([]*big.Int, 0, len(dupTokens))
	for _, token := range dupTokens {
		mergeTokens = append(mergeTokens, token)
		mergeAmounts = append(mergeAmounts, tokenAmountMap[token])
	}
	return mergeTokens, mergeAmounts
}
