package types

import (
	"encoding/hex"
	"errors"
	"math/big"
	"sort"

	"github.com/ethereum/go-ethereum/accounts/abi"
	"github.com/ethereum/go-ethereum/common"

	fxtypes "github.com/functionx/fx-core/v7/types"
)

const AssetERC20 = "erc20"

var FxcoreChainID = fxtypes.EIP155ChainID().String()

var (
	stringType        = mustABIType("string")
	bytesType         = mustABIType("bytes")
	addressArrayType  = mustABIType("address[]")
	uint256ArrayType  = mustABIType("uint256[]")
)

var (
	assetTypeArguments = abi.Arguments{
		{Type: stringType},
		{Type: bytesType},
	}

	erc20AssetArguments = abi.Arguments{
		{Type: addressArrayType},
		{Type: uint256ArrayType},
	}
)

func mustABIType(ts string) abi.Type {
	typ, err := abi.NewType(ts, "", nil)
	if err != nil {
		panic(err)
	}
	return typ
}

// UnpackAssetType unpacks the ABI encoded (string assetType, bytes assetData).
func UnpackAssetType(asset string) (string, []byte, error) {
	assetData, err := hex.DecodeString(asset)
	if err != nil {
		return "", nil, err
	}
	values, err := assetTypeArguments.Unpack(assetData)
	if err != nil {
		return "", nil, err
	}
	assetType, ok := values[0].(string)
	if !ok {
		return "", nil, errors.New("invalid asset type")
	}
	assetDataBz, ok := values[1].([]byte)
	if !ok {
		return "", nil, errors.New("invalid asset data")
	}
	return assetType, assetDataBz, nil
}

// UnpackERC20Asset unpacks the ABI encoded (address[] tokens, uint256[] amounts).
func UnpackERC20Asset(asset []byte) ([]common.Address, []*big.Int, error) {
	values, err := erc20AssetArguments.Unpack(asset)
	if err != nil {
		return nil, nil, err
	}
	tokens, ok := values[0].([]common.Address)
	if !ok {
		return nil, nil, errors.New("invalid tokens")
	}
	amounts, ok := values[1].([]*big.Int)
	if !ok {
		return nil, nil, errors.New("invalid amounts")
	}
	return tokens, amounts, nil
}

// MergeDuplicationERC20 merges the duplicate tokens and sums their amounts.
func MergeDuplicationERC20(tokens []common.Address, amounts []*big.Int) ([]common.Address, []*big.Int) {
	if len(tokens) != len(amounts) {
		return nil, nil
	}
	mergeTokenMap := make(map[common.Address]*big.Int, len(tokens))
	mergeTokens := make([]common.Address, 0, len(tokens))
	for i, token := range tokens {
		amount, ok := mergeTokenMap[token]
		if !ok {
			mergeTokens = append(mergeTokens, token)
			mergeTokenMap[token] = new(big.Int).Set(amounts[i])
			continue
		}
		mergeTokenMap[token] = amount.Add(amount, amounts[i])
	}
	sort.Slice(mergeTokens, func(i, j int) bool {
		return mergeTokens[i].String() < mergeTokens[j].String()
	})
	mergeAmounts := make([]*big.Int, 0, len(mergeTokens))
	for _, token := range mergeTokens {
		mergeAmounts = append(mergeAmounts, mergeTokenMap[token])
	}
	return mergeTokens, mergeAmounts
}

