	ibcPacketData := data.ToIBCPacketData()
	totalAmount := amount.Add(fee)
	if ibcPacketData.Denom == fxtypes.LegacyFXDenom {
		ibcPacketData.Denom = fxtypes.DefaultDenom
		totalAmount = fxtypes.SwapAmount(totalAmount)
	}
