	"github.com/ethereum/go-ethereum/common"
	"github.com/gogo/protobuf/proto"

	fxtypes "github.com/functionx/fx-core/v7/types"
)

const IbcCallTypeEvm = "ibc-call-evm"

var _ MemoPacket = (*IbcCallEvmPacket)(nil)

// MemoPacket is the interface that all memo packets must implement.
type MemoPacket interface {
	proto.Message
	GetType() IbcCallType
	ValidateBasic() error
}

// GetType returns the type of the ibc call.
func (p *IbcCallEvmPacket) GetType() IbcCallType {
	return IBC_CALL_TYPE_EVM
}

// ValidateBasic validates the ibc call evm packet.
func (p *IbcCallEvmPacket) ValidateBasic() error {
	if err := fxtypes.ValidateEthereumAddress(p.Target); err != nil {
		return errortypes.ErrInvalidRequest.Wrapf("invalid target: %s", err.Error())
	}
	value, ok := sdkmath.NewIntFromString(p.Value)
	if !ok {
		return errortypes.ErrInvalidRequest.Wrapf("invalid value: %s", p.Value)
	}
	if value.IsNegative() {
		return errortypes.ErrInvalidRequest.Wrapf("value must be non-negative: %s", p.Value)
	}
	if _, err := p.DecodeData(); err != nil {
		return errortypes.ErrInvalidRequest.Wrapf("invalid data: %s", err.Error())
	}
	return nil
}

// DecodeTarget returns the target contract address.
func (p *IbcCallEvmPacket) DecodeTarget() (common.Address, error) {
	if err := fxtypes.ValidateEthereumAddress(p.Target); err != nil {
		return common.Address{}, err
	}
	return common.HexToAddress(p.Target), nil
}

// DecodeData returns the decoded calldata.
func (p *IbcCallEvmPacket) DecodeData() ([]byte, error) {
	if strings.TrimSpace(p.Data) == "" {
		return nil, nil
	}
	return hex.DecodeString(p.Data)
}
```

