)

// IbcCallTypeEvm is the ibc call type name for evm call
const IbcCallTypeEvm = "ibc-call-evm"

// MemoPacket defines the interface for the ibc memo packet, the memo field of
// the fungible token packet data will be parsed to a `MemoPacket` when the
// packet is received on the destination chain.
type MemoPacket interface {
	proto.Message
	// GetType returns the type of the ibc call
	GetType() IbcCallType
	// ValidateBasic validates the memo packet
	ValidateBasic() error
}

var _ MemoPacket = (*IbcCallEvmPacket)(nil)

// GetType returns the type of the ibc call
func (p *IbcCallEvmPacket) GetType() IbcCallType {
	return IBC_CALL_TYPE_EVM
}

// ValidateBasic validates the ibc call evm packet
func (p *IbcCallEvmPacket) ValidateBasic() error {
	if err := fxtypes.ValidateEthereumAddress(p.GetTarget()); err != nil {
		return errortypes.ErrInvalidRequest.Wrapf("invalid target: %s", err.Error())
	}
	if _, ok := p.DecodeValue(); !ok {
		return errortypes.ErrInvalidRequest.Wrapf("invalid value: %s", p.GetValue())
	}
	if _, err := p.DecodeData(); err != nil {
		return errortypes.ErrInvalidRequest.Wrapf("invalid data: %s", err.Error())
	}
	return nil
}

// DecodeValue returns the value to send with the evm call
func (p *IbcCallEvmPacket) DecodeValue() (sdkmath.Int, bool) {
	if p.GetValue() == "" {
		return sdkmath.ZeroInt(), true
	}
	value, ok := sdkmath.NewIntFromString(p.GetValue())
	if !ok || value.IsNegative() {
		return sdkmath.Int{}, false
	}
	return value, true
}

// DecodeTarget returns the target contract address
func (p *IbcCallEvmPacket) DecodeTarget() (common.Address, error) {
	if err := fxtypes.ValidateEthereumAddress(p.GetTarget()); err != nil {
		return common.Address{}, err
	}
	return common.HexToAddress(p.GetTarget()), nil
}

// DecodeData returns the decoded calldata bytes
func (p *IbcCallEvmPacket) DecodeData() ([]byte, error) {
