package types

import (
	"crypto/sha256"
	"fmt"

	sdk "github.com/cosmos/cosmos-sdk/types"
)

// IntermediateAccountFromChannel returns the intermediate account address for
// the given source port, source channel and sender. The derived account is a
// deterministic account for a specific ibc sender, it is used as the caller of
// the ibc call evm.
func IntermediateAccountFromChannel(sourcePort, sourceChannel, sender string) sdk.AccAddress {
	// NOTE: the sender address is unique in the same channel, the intermediate
	// account is used to prevent a malicious sender from using the ibc call to
	// impersonate other accounts.
	senderHash32 := sha256.Sum256(append([]byte(fmt.Sprintf("%s/%s", sourcePort, sourceChannel)), []byte(sender)...))
	return sdk.AccAddress(senderHash32[:])
}

