package keeper

import (
	"strconv"

	sdk "github.com/cosmos/cosmos-sdk/types"
	sdkerrors "github.com/cosmos/cosmos-sdk/types/errors"
	"github.com/ethereum/go-ethereum/accounts/abi"
	"github.com/ethereum/go-ethereum/common"
	"github.com/ethereum/go-ethereum/core/vm"
	evmtypes "github.com/evmos/ethermint/x/evm/types"

	"github.com/functionx/fx-core/v7/x/ibc/applications/transfer/types"
)

// HandlerIbcCall handles the ibc call when the transfer packet contains a memo.
// The memo is interpreted as a json encoded `MemoPacket`, plain text memos or
// memos that don't match the expected structure are ignored.
func (k Keeper) HandlerIbcCall(ctx sdk.Context, sourcePort, sourceChannel string, data types.FungibleTokenPacketData) error {
	if len(data.Memo) == 0 {
		return nil
	}
	var mp types.MemoPacket
	if err := k.cdc.UnmarshalInterfaceJSON([]byte(data.Memo), &mp); err != nil {
		return nil
	}
	if err := mp.ValidateBasic(); err != nil {
		return err
	}
	switch packet := mp.(type) {
	case *types.IbcCallEvmPacket:
		return k.HandlerIbcCallEvm(ctx, sourcePort, sourceChannel, data, packet)
	default:
		return sdkerrors.ErrInvalidRequest.Wrapf("invalid ibc call type %s", mp.GetType())
	}
}

// HandlerIbcCallEvm executes the evm call with the ibc sender as the caller,
// the call is atomic with the token transfer, if the evm call fails the
// entire packet processing fails.
func (k Keeper) HandlerIbcCallEvm(ctx sdk.Context, sourcePort, sourceChannel string, data types.FungibleTokenPacketData, evmPacket *types.IbcCallEvmPacket) error {
	// the ibc sender is derived from the source port, source channel and sender
	sender := types.IntermediateAccountFromChannel(sourcePort, sourceChannel, data.Sender)
	if !k.authKeeper.HasAccount(ctx, sender) {
		k.authKeeper.SetAccount(ctx, k.authKeeper.NewAccountWithAddress(ctx, sender))
	}

	contract, err := evmPacket.DecodeTarget()
	if err != nil {
		return err
	}
	value, ok := evmPacket.DecodeValue()
	if !ok {
		return sdkerrors.ErrInvalidRequest.Wrapf("invalid evm value: %s", evmPacket.Value)
	}
	dataBytes, err := evmPacket.DecodeData()
	if err != nil {
		return err
	}

	evmErrCause, evmSuccess := "", false
	defer func() {
		attrs := []sdk.Attribute{
			sdk.NewAttribute(types.AttributeKeyType, evmPacket.GetType().String()),
			sdk.NewAttribute(sdk.AttributeKeySender, common.BytesToAddress(sender).String()),
			sdk.NewAttribute(types.AttributeKeySuccess, strconv.FormatBool(evmSuccess)),
		}
		if len(evmErrCause) > 0 {
			attrs = append(attrs, sdk.NewAttribute(types.AttributeKeyErrCause, evmErrCause))
		}
		ctx.EventManager().EmitEvent(sdk.NewEvent(types.EventTypeIBCCall, attrs...))
	}()

	res, err := k.evmKeeper.CallEVM(ctx, common.BytesToAddress(sender), &contract, value.BigInt(), evmPacket.GasLimit, dataBytes, true)
	if err != nil {
		evmErrCause = err.Error()
		return err
	}
	evmSuccess = !res.Failed()
	evmErrCause = res.VmError
	if res.Failed() {
		errStr := res.VmError
		if res.VmError == vm.ErrExecutionReverted.Error() {
			if reason, unpackErr := abi.UnpackRevert(common.CopyBytes(res.Ret)); unpackErr == nil {
				errStr = reason
			}
		}
		return evmtypes.ErrVMExecution.Wrap(errStr)
	}
	return nil
}

