func (suite *KeeperTestSuite) TestHandlerIbcCallEvmEvent() {
	suite.SetupTest()
	sourcePort := "transfer"
	sourceChannel := "channel-0"
	data := fxtransfertypes.FungibleTokenPacketData{
		Denom:  fxtypes.DefaultDenom,
		Amount: "1",
		Sender: "sender",
		Memo:   fmtIbcCallEvmMemo(suite.T(), helpers.GenerateAddress().String(), "0", 0, ""),
	}

	err := suite.GetApp(suite.chainA.App).FxTransferKeeper.HandlerIbcCall(suite.chainA.GetContext(), sourcePort, sourceChannel, data)
	suite.Require().NoError(err)

	var callEvent *sdk.Event
	for _, event := range suite.chainA.GetContext().EventManager().Events() {
		event := event
		if event.Type == fxtransfertypes.EventTypeIBCCall {
			callEvent = &event
		}
	}
	suite.Require().NotNil(callEvent)
	attrs := callEvent.Attributes
	suite.Require().Equal(fxtransfertypes.IBC_CALL_TYPE_EVM.String(), string(attrs[0].Value))
	suite.Require().Equal(common.BytesToAddress(callerAddr(sourcePort, sourceChannel, data.Sender)).String(), string(attrs[1].Value))
	suite.Require().Equal("true", string(attrs[2].Value))
}

func callerAddr(sourcePort, sourceChannel, sender string) sdk.AccAddress {
	return fxtransfertypes.IntermediateAccountFromChannel(sourcePort, sourceChannel, sender)
}

func fmtIbcCallEvmMemo(t *testing.T, target, value string, gasLimit uint64, data string) string {
	memoBz, err := json.Marshal(map[string]interface{}{
		"@type":     "/fx.ibc.applications.transfer.v1.IbcCallEvmPacket",
		"target":    target,
		"value":     value,
		"gas_limit": gasLimit,
		"data":      data,
	})
	require.NoError(t, err)
	return string(memoBz)
}

