package main

import (
	"bytes"
	"compress/gzip"
	"fmt"
	"io/ioutil"
	"os"
	"strconv"
	"strings"

	"github.com/gogo/protobuf/proto"
	"github.com/gogo/protobuf/protoc-gen-gogo/descriptor"
)

func main() {
	pbPath := os.Args[1]
	src, err := ioutil.ReadFile(pbPath)
	if err != nil {
		panic(err)
	}
	lines := strings.Split(string(src), "\n")
	start, end := -1, -1
	for i, l := range lines {
		if strings.HasPrefix(l, "var fileDescriptor_60fb0411450507d8 = []byte{") {
			start = i
		}
		if start >= 0 && i > start && strings.TrimSpace(l) == "}" {
			end = i
			break
		}
	}
	if start < 0 || end < 0 {
		panic("descriptor not found")
	}
	var raw []byte
	for _, l := range lines[start+1 : end] {
		t := strings.TrimSpace(l)
		if t == "" || strings.HasPrefix(t, "//") {
			continue
		}
		for _, f := range strings.Split(t, ",") {
			f = strings.TrimSpace(f)
			if f == "" {
				continue
			}
			b, err := strconv.ParseUint(f, 0, 8)
			if err != nil {
				panic(err)
			}
			raw = append(raw, byte(b))
		}
	}
	zr, err := gzip.NewReader(bytes.NewReader(raw))
	if err != nil {
		panic(err)
	}
	decompressed, err := ioutil.ReadAll(zr)
	if err != nil {
		panic(err)
	}
	var fd descriptor.FileDescriptorProto
	if err := proto.Unmarshal(decompressed, &fd); err != nil {
		panic(err)
	}
	if fd.GetName() != "fx/ibc/applications/transfer/v1/transfer.proto" {
		panic("wrong file name: " + fd.GetName())
	}
	if len(fd.MessageType) != 2 {
		panic(fmt.Sprintf("expected 2 messages, got %d", len(fd.MessageType)))
	}
	if fd.MessageType[0].GetName() != "FungibleTokenPacketData" || fd.MessageType[1].GetName() != "IbcCallEvmPacket" {
		panic(fmt.Sprintf("unexpected messages: %s, %s", fd.MessageType[0].GetName(), fd.MessageType[1].GetName()))
	}
	evm := fd.MessageType[1]
	if len(evm.Field) != 4 {
		panic(fmt.Sprintf("expected 4 fields, got %d", len(evm.Field)))
	}
	for _, fld := range evm.Field {
		fmt.Printf("  field %d: %s (%s)\n", fld.GetNumber(), fld.GetName(), fld.GetType())
	}
	if len(fd.EnumType) != 1 || fd.EnumType[0].GetName() != "IbcCallType" {
		panic("enum not found")
	}
	for _, v := range fd.EnumType[0].Value {
		fmt.Printf("  enum value: %s = %d\n", v.GetName(), v.GetNumber())
	}
	fmt.Println("OK: descriptor is valid and complete")
}

